PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS dim_date(date_key INTEGER PRIMARY KEY, full_date TEXT NOT NULL, year INTEGER NOT NULL, quarter INTEGER NOT NULL, month INTEGER NOT NULL, month_name TEXT NOT NULL, week_of_year INTEGER NOT NULL, day_of_week INTEGER NOT NULL, is_weekend INTEGER NOT NULL CHECK(is_weekend IN(0,1)), period_phase TEXT NOT NULL CHECK(period_phase IN('baseline_manual','assisted_3eyes')));
CREATE TABLE IF NOT EXISTS dim_shift(shift_key INTEGER PRIMARY KEY, shift_name TEXT NOT NULL, start_hour INTEGER NOT NULL, end_hour INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS dim_inspector(inspector_key INTEGER PRIMARY KEY, inspector_code TEXT NOT NULL UNIQUE, tenure_years REAL NOT NULL, experience_band TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS dim_device(device_key INTEGER PRIMARY KEY, device_code TEXT NOT NULL UNIQUE, model_version TEXT NOT NULL, deployed_date TEXT);
CREATE TABLE IF NOT EXISTS dim_lot(lot_key INTEGER PRIMARY KEY, lot_code TEXT NOT NULL UNIQUE, customer_name TEXT NOT NULL, production_line TEXT NOT NULL, lot_size INTEGER NOT NULL CHECK(lot_size>0), production_date TEXT NOT NULL, shift_key INTEGER NOT NULL REFERENCES dim_shift(shift_key));
CREATE TABLE IF NOT EXISTS dim_defect(defect_key INTEGER PRIMARY KEY, defect_name TEXT NOT NULL UNIQUE, defect_group TEXT NOT NULL, location TEXT NOT NULL, severity TEXT NOT NULL CHECK(severity IN('none','minor','major','critical')), is_defect INTEGER NOT NULL CHECK(is_defect IN(0,1)));
CREATE TABLE IF NOT EXISTS dim_scenario(scenario_key INTEGER PRIMARY KEY, scenario_name TEXT NOT NULL, description TEXT);
CREATE TABLE IF NOT EXISTS fact_inspection(inspection_id INTEGER PRIMARY KEY, unit_id TEXT NOT NULL, date_key INTEGER NOT NULL REFERENCES dim_date(date_key), shift_key INTEGER NOT NULL REFERENCES dim_shift(shift_key), inspector_key INTEGER NOT NULL REFERENCES dim_inspector(inspector_key), device_key INTEGER REFERENCES dim_device(device_key), lot_key INTEGER NOT NULL REFERENCES dim_lot(lot_key), scenario_key INTEGER NOT NULL REFERENCES dim_scenario(scenario_key), true_defect_key INTEGER NOT NULL REFERENCES dim_defect(defect_key), inspection_mode TEXT NOT NULL CHECK(inspection_mode IN('manual','assisted')), hour_in_shift INTEGER NOT NULL CHECK(hour_in_shift BETWEEN 1 AND 8), lighting_cond TEXT NOT NULL CHECK(lighting_cond IN('good','dim','glare')), device_decision TEXT CHECK(device_decision IN('PASS','FAIL','UNCERTAIN')), final_decision TEXT NOT NULL CHECK(final_decision IN('PASS','FAIL')), override_flag INTEGER NOT NULL DEFAULT 0 CHECK(override_flag IN(0,1)), inspect_seconds REAL NOT NULL CHECK(inspect_seconds>0), UNIQUE(unit_id,inspection_mode,scenario_key));
CREATE TABLE IF NOT EXISTS fact_customer_claim(claim_id INTEGER PRIMARY KEY, date_key INTEGER NOT NULL REFERENCES dim_date(date_key), lot_key INTEGER NOT NULL REFERENCES dim_lot(lot_key), defect_key INTEGER NOT NULL REFERENCES dim_defect(defect_key), scenario_key INTEGER NOT NULL REFERENCES dim_scenario(scenario_key), qty_returned INTEGER NOT NULL CHECK(qty_returned>=0), claim_cost REAL NOT NULL CHECK(claim_cost>=0), rework_cost REAL NOT NULL CHECK(rework_cost>=0), UNIQUE(lot_key,defect_key,scenario_key));
CREATE TABLE IF NOT EXISTS fact_lot_summary(lot_key INTEGER NOT NULL REFERENCES dim_lot(lot_key), scenario_key INTEGER NOT NULL REFERENCES dim_scenario(scenario_key), inspection_mode TEXT NOT NULL, units_inspected INTEGER NOT NULL, true_defects INTEGER NOT NULL, defects_caught INTEGER NOT NULL, defects_escaped INTEGER NOT NULL, final_false_rejects INTEGER NOT NULL, labor_cost REAL NOT NULL, claim_cost REAL NOT NULL, PRIMARY KEY(lot_key,scenario_key,inspection_mode));
CREATE TABLE IF NOT EXISTS etl_run_log(run_id INTEGER PRIMARY KEY AUTOINCREMENT, started_at TEXT NOT NULL, finished_at TEXT, step_name TEXT NOT NULL, rows_read INTEGER, rows_loaded INTEGER, rows_rejected INTEGER, status TEXT NOT NULL CHECK(status IN('running','success','failed','partial')), message TEXT);
CREATE TABLE IF NOT EXISTS etl_quarantine(quarantine_id INTEGER PRIMARY KEY AUTOINCREMENT, run_id INTEGER NOT NULL REFERENCES etl_run_log(run_id), source_table TEXT NOT NULL, raw_row_json TEXT NOT NULL, reject_reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ix_fi_date ON fact_inspection(date_key);
CREATE INDEX IF NOT EXISTS ix_fi_lot ON fact_inspection(lot_key);
CREATE INDEX IF NOT EXISTS ix_fi_mode_scn ON fact_inspection(inspection_mode,scenario_key);
CREATE INDEX IF NOT EXISTS ix_fi_defect ON fact_inspection(true_defect_key);
CREATE INDEX IF NOT EXISTS ix_fc_lot ON fact_customer_claim(lot_key);
